// Deterministic validation before any processing.
const body = $json.body || $json;
if (!body.session_id) {
  return [{ json: { valid: false, status: 'ERROR', error: 'VALIDATION_ERROR', message: 'session_id is mandatory' } }];
}
const risk = String(body.action_risk || 'MEDIUM').toUpperCase();
if (!['LOW', 'MEDIUM', 'HIGH', 'FINANCIAL'].includes(risk)) {
  return [{ json: { valid: false, status: 'ERROR', error: 'INVALID_RISK_TIER', message: 'Unsupported action_risk' } }];
}
return [{
  json: {
    valid: true,
    session_id: String(body.session_id),
    caller_id: String(body.caller_id || 'unknown'),
    action_risk: risk,
    audio_path: body.audio_path || null,
    sample_rate: body.sample_rate || null,
    audio_report: body.audio_report || null,
    preferred_language: body.preferred_language || null,
    enrolled_language: body.enrolled_language || null,
    current_language: body.current_language || null,
    transcript_text: body.transcript_text || null,
    language_confidence: body.language_confidence !== undefined ? body.language_confidence : null,
    webrtc_stats: body.webrtc_stats || null,
    aletheia: body.aletheia || null,
    eidos: body.eidos || null,
    detection_result: body.detection_result || null,
    agent_findings: body.agent_findings || null,
    use_gemini: body.use_gemini !== false,
    simulation_mode: body.simulation_mode === true
  }
}];

// Deterministic routing metadata; the backend executes only relevant agents concurrently.
const req = $('Validate Input').first().json;
const pre = $json;
const planned = ['speech_sufficiency', 'acoustic_intelligence', 'network_resilience', 'regional_language'];
if (req.eidos || req.enrolled_language || (req.current_language && req.enrolled_language && req.current_language !== req.enrolled_language)) {
  planned.push('cross_language_identity');
}
return [{ json: { ...req, audio_report: pre, planned_agents: planned } }];

// Reuse agent findings; never re-run audio processing.
const req = $('Agent Routing').first().json;
const agents = $json;
return [{ json: { ...req, agent_findings: agents.agent_findings || {}, activated_agents: agents.activated_agents || [], agent_errors: agents.errors || [] } }];

// Only the validated trust facts are sent to the recovery phrasing stage.
const req = $('Trust Input').first().json;
const trust = $json;
const td = trust.trust_decision || {};
return [{ json: { session_id: req.session_id, verification_status: td.verification_status || null, decision: td.decision || null, session_state: td.session_state || null, reason_codes: td.reason_codes || [], recovery_action: trust.recovery_action || null, agent_findings: req.agent_findings || {}, preferred_language: trust.preferred_language || req.preferred_language || 'en', use_gemini: req.use_gemini !== false } }];

// Assemble the backward-compatible unified response.
const req = $('Trust Input').first().json;
const trust = $('Detectif AI and Trust Engine').first().json;
const pre = $('Audio Pre-checks').first().json;
const rec = $json;
const td = trust.trust_decision || {};
return [{ json: {
  session_id: req.session_id,
  activated_agents: trust.activated_agents || req.activated_agents || [],
  agent_findings: trust.agent_findings || req.agent_findings || {},
  detection_result: trust.detection_result || {},
  identity_result: trust.identity_result || {},
  trust_decision: td,
  decision_reasons: trust.decision_reasons || td.reason_codes || [],
  recovery_action: rec.recovery_action !== undefined ? rec.recovery_action : (trust.recovery_action || null),
  customer_message: rec.customer_message || trust.customer_message || '',
  preferred_language: rec.preferred_language || trust.preferred_language || 'en',
  processing_time_ms: Math.round(((pre.processing_time_ms || 0) + (trust.processing_time_ms || 0) + (rec.processing_time_ms || 0)) * 100) / 100,
  errors: [...(trust.errors || []), ...(req.agent_errors || []), ...(rec.validation_errors || [])],
  simulation_mode: !!(trust.simulation_mode || req.simulation_mode),
  outcome: trust.outcome || td.outcome,
  verification_status: td.verification_status,
  decision: td.decision,
  session_state: td.session_state,
  recovery_details: rec
} }];
